package glitch

import data.glitch_lib

gpg_check_attrs := {"gpgcheck", "repo_gpgcheck"}

disabled_integrity_attrs := {"disable_gpg_check", "skip_checksum", "no_checksum", "checksum_disabled", "gpg_autoimport_keys", "skip_tls_verify", "insecure"}

tls_verify_attrs := {"verify_ssl", "tls_verify", "ssl_verify", "validate_certs"}

sig_verify_attrs := {"signature_check", "enforce_signing"}

source_url_attrs := {"url", "source", "src", "repo", "baseurl", "mirrorlist"}

download_resource_types := {"get_url", "remote_file", "maven_artifact", "fetch", "s3_object", "artifact_deploy"}

integrity_attr_names := {"checksum", "sha256", "sha512", "sha1", "md5", "hash", "digest", "integrity"}

is_falsy(value) {
    value.ir_type == "Integer"
    value.value == 0
}

is_falsy(value) {
    value.ir_type == "Boolean"
    value.value == false
}

is_falsy(value) {
    value.ir_type == "String"
    lower(value.value) == "no"
}

is_truthy(value) {
    value.ir_type == "Boolean"
    value.value == true
}

has_integrity_attr(node) {
    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]
    attr.name == integrity_attr_names[_]
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]
    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]
    attr.name == gpg_check_attrs[_]
    is_falsy(attr.value)
    result := {
        "type": "sec_no_int_check",
        "element": attr,
        "path": parent.path,
        "description": "Missing Support for Integrity Check - Package GPG check is disabled, allowing unverified packages to be installed. (CWE-353)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    walk(parent, [_, node])
    node.ir_type == "Hash"
    entry := node.value[_]
    entry.key.ir_type == "String"
    entry.key.value == gpg_check_attrs[_]
    is_falsy(entry.value)
    result := {
        "type": "sec_no_int_check",
        "element": entry.value,
        "path": parent.path,
        "description": "Missing Support for Integrity Check - Package GPG check is disabled in nested configuration. (CWE-353)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]
    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]
    attr.name == disabled_integrity_attrs[_]
    is_truthy(attr.value)
    result := {
        "type": "sec_no_int_check",
        "element": attr,
        "path": parent.path,
        "description": "Missing Support for Integrity Check - Integrity or checksum verification is explicitly disabled. (CWE-353)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]
    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]
    attr.name == tls_verify_attrs[_]
    is_falsy(attr.value)
    result := {
        "type": "sec_no_int_check",
        "element": attr,
        "path": parent.path,
        "description": "Missing Support for Integrity Check - TLS/SSL verification is disabled, removing transport-level integrity guarantees. (CWE-353)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]
    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]
    attr.name == sig_verify_attrs[_]
    is_falsy(attr.value)
    result := {
        "type": "sec_no_int_check",
        "element": attr,
        "path": parent.path,
        "description": "Missing Support for Integrity Check - Signature verification is disabled for a module or provider. (CWE-353)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]
    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]
    attr.name == "image"
    attr.value.ir_type == "String"
    not regex.match("@sha256:", attr.value.value)
    result := {
        "type": "sec_no_int_check",
        "element": attr,
        "path": parent.path,
        "description": "Missing Support for Integrity Check - Container image is referenced without an immutable cryptographic digest (@sha256:). (CWE-353)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]
    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]
    attr.name == source_url_attrs[_]
    attr.value.ir_type == "String"
    startswith(attr.value.value, "http://")
    result := {
        "type": "sec_no_int_check",
        "element": attr,
        "path": parent.path,
        "description": "Missing Support for Integrity Check - Artifact or package source uses insecure HTTP, lacking transport integrity. (CWE-353)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]
    node.type == download_resource_types[_]
    not has_integrity_attr(node)
    result := {
        "type": "sec_no_int_check",
        "element": node,
        "path": parent.path,
        "description": "Missing Support for Integrity Check - Download task lacks checksum or integrity verification. (CWE-353)"
    }
}

